package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.time.StopWatch#unsplit()
 */
public class StopWatch_unsplit_TriageGen1Test {

    @Test
    public void testUnsplit_WhenNotSplit_ThrowsIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        // Initial state is UNSPLIT, calling unsplit should throw exception
        try {
            stopWatch.unsplit();
            Assert.fail("Expected IllegalStateException to be thrown");
        } catch (IllegalStateException e) {
            Assert.assertEquals("Stopwatch has not been split. ", e.getMessage());
        }
    }

    @Test
    public void testUnsplit_WhenSplit_SuccessfullyUnsplits() {
        StopWatch stopWatch = new StopWatch();

        // Setup: Start and then split
        stopWatch.start();
        stopWatch.split();

        // Verify state is split (implicitly by checking it doesn't throw)
        // We can't directly check private fields, but we can check behavior
        stopWatch.unsplit();

        // After unsplit, calling unsplit again should throw exception because state is now UNSPLIT
        try {
            stopWatch.unsplit();
            Assert.fail("Expected IllegalStateException to be thrown after unsplitting");
        } catch (IllegalStateException e) {
            Assert.assertEquals("Stopwatch has not been split. ", e.getMessage());
        }
    }

    @Test
    public void testUnsplit_AfterStop_SuccessfullyUnsplits() {
        StopWatch stopWatch = new StopWatch();

        stopWatch.start();
        stopWatch.split();
        stopWatch.stop();

        // Ensure unsplit works even if the watch is stopped
        stopWatch.unsplit();

        // Verify it's back to unsplit state
        try {
            stopWatch.unsplit();
            Assert.fail("Expected IllegalStateException");
        } catch (IllegalStateException e) {
            // Success
        }
    }

    @Test
    public void testUnsplit_AfterReset_ThrowsIllegalStateException() {
        StopWatch stopWatch = new StopWatch();

        stopWatch.start();
        stopWatch.split();
        stopWatch.reset(); // reset sets state back to UNSPLIT

        try {
            stopWatch.unsplit();
            Assert.fail("Expected IllegalStateException after reset");
        } catch (IllegalStateException e) {
            Assert.assertEquals("Stopwatch has not been split. ", e.getMessage());
        }
    }
}
